/* From Uiverse.io by vinodjangid07  - Tags: black, notification, button, hover effect, inbox */
.__UIV_SCOPE__ .inbox-btn {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  border: none;
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.082);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  background-color: #464646;
  cursor: pointer;
  transition: all 0.3s;
}
.__UIV_SCOPE__ .inbox-btn svg path {
  fill: white;
}
.__UIV_SCOPE__ .inbox-btn svg {
  height: 17px;
  transition: all 0.3s;
}
.__UIV_SCOPE__ .msg-count {
  position: absolute;
  top: -5px;
  right: -5px;
  background-color: rgb(255, 255, 255);
  border-radius: 50%;
  font-size: 0.7em;
  color: rgb(0, 0, 0);
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.__UIV_SCOPE__ .inbox-btn:hover {
  transform: scale(1.1);
}
